const { files } = $('HTTP: Lista Arquivos LAB').first().json;
const raw = $input.first().json;
const indexed = raw.body || raw;
const indexedMap = {};
(Array.isArray(indexed) ? indexed : []).forEach(d => {
  if (d.external_id) indexedMap[d.external_id] = d.drive_modified_at;
});

if (!files || files.length === 0) throw new Error('SKIP: nenhum arquivo retornado pelo GAS');

const toProcess = files.filter(f => {
  const lastIndexed = indexedMap[f.id];
  if (!lastIndexed) return true;
  return new Date(f.modifiedTime) > new Date(lastIndexed);
});

if (toProcess.length === 0) throw new Error('SKIP: todos os arquivos já estão atualizados');
return toProcess.map(f => ({ json: f }));

const f = $input.first().json;
const mime = f.mimeType || '';

const EXPORTABLE = new Set([
  'application/vnd.google-apps.document',
  'application/vnd.google-apps.presentation',
  'application/vnd.google-apps.spreadsheet',
  'application/vnd.google-apps.drawing',
]);
const isGoogleNative = EXPORTABLE.has(mime);

const extractOpMap = {
  'application/pdf': 'pdf',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'word',
  'application/msword': 'word',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'word',
  'application/vnd.ms-powerpoint': 'word',
  'text/plain': 'text',
  'text/markdown': 'text',
  'text/x-markdown': 'text',
  'text/csv': 'text',
  'application/csv': 'text',
};
const extractOp = isGoogleNative ? 'pdf' : (extractOpMap[mime] || null);

if (!extractOp) {
  return [{ json: { _skip: true, _reason: 'tipo não suportado: ' + mime, fileName: f.name } }];
}

return [{ json: {
  ...f,
  isGoogleNative,
  extractOp,
  driveFileId:        f.id,
  driveModifiedAt:    f.modifiedTime,
  fileName:           f.name,
  mimeType:           mime,
  driveFolderWatchId: '1WIjp8kdnVIMmt2yBSgoHYSvxvcfGEK3_',
  supabaseUrl:        'https://alrnajijumqvxzmogwpy.supabase.co',
  supabaseServiceKey: '***REMOVIDO***',
} }];

const rawText = $input.first().json.text || $input.first().json.data || '';
const cfg = $('Code: Classifica Arquivo').first().json;

function stripMarkdown(txt) {
  return txt
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/\*(.+?)\*/g, '$1')
    .replace(/_{2}(.+?)_{2}/g, '$1')
    .replace(/`{3}[\s\S]*?`{3}/gm, '')
    .replace(/`(.+?)`/g, '$1')
    .replace(/^\s*[-*+]\s+/gm, '')
    .replace(/^\s*\d+\.\s+/gm, '')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/!\[.*?\]\([^)]+\)/g, '')
    .replace(/^>\s*/gm, '')
    .replace(/^---+$/gm, '')
    .trim();
}

const isMarkdown = /\.(md|markdown)$/i.test(cfg.fileName || '');
const cleaned = rawText.replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n').replace(/[ \t]{2,}/g, ' ').trim();
const text = isMarkdown ? stripMarkdown(cleaned) : cleaned;

if (text.length < 30) {
  return [{ json: { _skip: true, _reason: 'texto muito curto', fileName: cfg.fileName } }];
}

const CHUNK_SIZE = 800, OVERLAP = 120;
const chunks = [];
let start = 0;
while (start < text.length) {
  const end = Math.min(start + CHUNK_SIZE, text.length);
  const content = text.slice(start, end).trim();
  if (content.length > 20) chunks.push({ content, chunkIndex: chunks.length });
  if (end >= text.length) break;
  start += CHUNK_SIZE - OVERLAP;
}

if (chunks.length === 0) {
  return [{ json: { _skip: true, _reason: 'sem chunks gerados', fileName: cfg.fileName } }];
}

return [{ json: {
  chunks,
  totalChunks:        chunks.length,
  driveFileId:        cfg.driveFileId,
  driveModifiedAt:    cfg.driveModifiedAt,
  fileName:           cfg.fileName,
  mimeType:           cfg.mimeType,
  driveFolderWatchId: cfg.driveFolderWatchId,
  supabaseUrl:        cfg.supabaseUrl,
  supabaseServiceKey: cfg.supabaseServiceKey,
} }];

const embedData  = $input.first().json.data;
const ctx        = $('Code: Divide em Chunks').first().json;
const upsertResp = $('HTTP: Upsert Documento').first().json;
const documentId = upsertResp.body?.[0]?.id || upsertResp?.[0]?.id;
if (!documentId) return [{ json: { _skip: true, _reason: 'document_id não encontrado', fileName: ctx.fileName } }];
const rows = ctx.chunks.map((c, i) => ({
  document_id: documentId,
  content:     c.content,
  embedding:   embedData[i]?.embedding || [],
  chunk_index: c.chunkIndex,
  page:        null,
}));
return [{ json: { rows, totalChunks: rows.length, documentId, supabaseUrl: ctx.supabaseUrl, supabaseServiceKey: ctx.supabaseServiceKey, fileName: ctx.fileName } }];

